  cm.opacity = lerp(cm.opacity, 1 - A.cloudNightOpacity * night, gray);
  cm.color.copy(base.cloudColor).lerp(tmp.copy(C.cloudGray).lerp(C.cloudStorm, stormK), gray).multiplyScalar(lerp(1, A.cloudNightDim, night));
