  const wu = water.material.uniforms, wc = wu.waterColor.value as THREE.Color;
  wc.lerp(tmp.copy(C.waterSun).multiplyScalar(dark), sunny).lerp(tmp.copy(C.waterRain).lerp(C.waterStorm, stormK).multiplyScalar(dark), gray);
