  const setData = (e: HTMLElement, k: string, v: string) => { if (e.dataset[k] !== v) e.dataset[k] = v; };
  const setStyle = (e: HTMLElement | SVGElement, k: string, v: string) => { if (e.style.getPropertyValue(k) !== v) e.style.setProperty(k, v); };
